import json, os

H = os.path.dirname(os.path.abspath(__file__))


def mv(side, commander, label, path):
    return {"side": side, "commander": commander, "label": label, "path": path}


def ev(name, kind, lon, lat, year, winner, text):
    return {"name": name, "kind": kind, "lon": lon, "lat": lat, "year": year, "winner": winner, "text": text}


def fr(path, label):
    return {"path": path, "label": label}


def terr(*groups):
    return [{"side": s, "polities": p} for s, p in groups if p]


def step(year, label, title, text, territories, moves, events, fronts=None):
    return {"year": year, "label": label, "title": title, "text": text,
            "territories": territories, "fronts": fronts or [], "moves": moves, "events": events}


